    /**
     * TC-031 - Verify that the system does not allow setting the order ID via the request body,
     * preventing ID manipulation.
     */
    @Test
    public void verifyOrderIdCannotBeSetViaRequestBody() {
        String requestBody = """
            {
              "id": 999,
              "customerName": "Charlie",
              "productName": "Widget",
              "quantity": 1,
              "price": 10.0
            }
            """;
        Integer returnedId = given().contentType(ContentType.JSON).body(requestBody).when().post("/orders").then().statusCode(200).body("id", not(equalTo(999))).extract().path("id");
        Assert.assertNotNull(returnedId, "Returned order ID should not be null");
    }

    /**
     * TC-032 - Verify that error responses do not leak internal details or stack traces when
     * an invalid order ID is requested.
     */
    @Test
    public void verifyErrorResponseDoesNotLeakInternalDetails() {
        String responseBody = given().when().get("/orders/9999").then().statusCode(anyOf(is(404), is(204))).extract().asString();
        // Assert no stack trace or internal details in response
        Assert.assertTrue(responseBody.isEmpty() || responseBody.toLowerCase().contains("not found"), "Response should be empty or contain a generic error message. Body was: " + responseBody);
    }

    /**
     * TC-033 - Verify that special characters in productName or customerName do not cause
     * injection or malformed responses.
     */
    @Test
    public void verifySpecialCharactersInNamesDoNotCauseInjection() {
        String requestBody = """
            {
              "customerName": "<script>alert('xss')</script>",
              "productName": "Widget'; DROP TABLE orders;--",
              "quantity": 1,
              "price": 10.0
            }
            """;
        // Step 1: Create order with special characters
        Integer orderId = given().contentType(ContentType.JSON).body(requestBody).when().post("/orders").then().statusCode(200).extract().path("id");
        Assert.assertNotNull(orderId, "Order ID should not be null");
        // Step 2: Retrieve the order and verify special characters are preserved
        given().when().get("/orders/{id}", orderId).then().statusCode(200).body("customerName", equalTo("<script>alert('xss')</script>")).body("productName", equalTo("Widget'; DROP TABLE orders;--"));
    }

